function UpdateJCOHeaderPrice(sJCOHeaderId,sQuoteId)
{
	try{
		var theApp = TheApplication();
		var JCOHeaderBC = theApp.GetBusObject("MF Service Order").GetBusComp("MF Service Order");
		var QuoteHeaderBC = theApp.GetBusObject("MF Quote Service BO").GetBusComp("MF Quote Service");
		var LbrLstPriTot = "";
		var LbrDiscTot = "";
		var LbrSalePriTot = "";
		var PartsLstPriTot = "";
        var PartsDiscTot = "";
		var PartsSalePriTot = "";


		with(QuoteHeaderBC){
			ActivateField("MF Labor Total Unit Amnt");
			ActivateField("MF Labor Total Disc Amnt");
			ActivateField("MF Labor Total Amount Calc Custom");
			ActivateField("MF Parts Total Unit Amnt");
			ActivateField("MF Parts Total Disc Amnt");
			ActivateField("MF Parts Total Amount Calc Custom");
			SetViewMode(AllView);
			ClearToQuery();
			SetSearchSpec("Id",sQuoteId);
			ExecuteQuery(ForwardOnly);
			if(FirstRecord()){
				LbrLstPriTot = GetFieldValue("MF Labor Total Unit Amnt");
				LbrDiscTot = GetFieldValue("MF Labor Total Disc Amnt");
				LbrSalePriTot = GetFieldValue("MF Labor Total Amount Calc Custom");
				PartsLstPriTot = GetFieldValue("MF Parts Total Unit Amnt");
				PartsDiscTot = GetFieldValue("MF Parts Total Disc Amnt");
				PartsSalePriTot = GetFieldValue("MF Parts Total Amount Calc Custom");
			}	
		}

		with(JCOHeaderBC){
			ActivateField("MF Labor Total Amount WTax");
			ActivateField("MF Labor Total Disc Amnt");
			ActivateField("MF Labor Total Unit Price");
			ActivateField("MF Parts Total Amount WTax");
			ActivateField("MF Parts Total Disc Amnt");
			ActivateField("MF Parts Total Unit Price");
			SetViewMode(AllView);
			ClearToQuery();
			var sExpr = "[Id] = '" + sJCOHeaderId + "' AND [Order Type] = LookupValue('FS_ORDER_TYPE','Job Card Order')";
			SetSearchExpr(sExpr);
			ExecuteQuery(ForwardOnly);
			var isRec = FirstRecord();
			if(isRec){
				JCOHeaderBC.SetFieldValue("MF Labor Total Unit Price",LbrLstPriTot);
				JCOHeaderBC.SetFieldValue("MF Labor Total Disc Amnt",LbrDiscTot);
				JCOHeaderBC.SetFieldValue("MF Labor Total Amount WTax",LbrSalePriTot);
				JCOHeaderBC.SetFieldValue("MF Parts Total Unit Price",PartsLstPriTot);
				JCOHeaderBC.SetFieldValue("MF Parts Total Amount WTax",PartsSalePriTot);
				JCOHeaderBC.SetFieldValue("MF Parts Total Disc Amnt",PartsDiscTot);
				JCOHeaderBC.WriteRecord();
			}
		}
	}

	catch(e){
		throw(e);
	}

	finally{
		isRec = null;
		sExpr = null;
		PartsSalePriTot = null;
		PartsDiscTot = null;
		PartsLstPriTot = null;
		LbrSalePriTot = null;
		LbrDiscTot = null;
		LbrLstPriTot = null;
		QuoteHeaderBC = null;
		JCOHeaderBC = null;
		theApp = null;
	}
}

